// The example app's Xcode project, generated by Tuist. Run `tuist generate --path Example` on a
// Mac; no `.xcodeproj` or `.xcworkspace` is committed.

import ProjectDescription

// iPhone only: the screens are designed for a compact width.
let destinations: Destinations = [
    .iPhone,
]

let deploymentTargets = DeploymentTargets.iOS("17.0")

let baseSettings: SettingsDictionary = [
    "SWIFT_VERSION": "6.0",
    "SWIFT_STRICT_CONCURRENCY": "complete",
]

let infoPlistValues: [String: Plist.Value] = [
    "CFBundleDisplayName": "Waypoint",
    "UILaunchScreen": [:],
    "UISupportedInterfaceOrientations": ["UIInterfaceOrientationPortrait"],
]

let appSources: SourceFilesList = [
    "WaypointExample/**",
]

// The asset catalog holds the app icon: the identity's day icon, and its night icon in dark mode.
let appResources: ResourceFileElements = [
    "WaypointExample/Resources/**",
]

// The app has no accent color asset, so the empty name stops the catalog warning about a missing
// one. Testability stays on in Release too, because the Release UI test run builds the whole
// scheme, and the unit tests reach the app's view models with `@testable import`.
//
// The app's code is main actor by default (Swift 6.2's default actor isolation), so it writes no
// `@MainActor`; code that runs elsewhere says so with `nonisolated` or `@concurrent`. See
// CODE_STYLE.md. The package itself writes every isolation explicitly.
let appSettings: SettingsDictionary = [
    "ASSETCATALOG_COMPILER_APPICON_NAME": "AppIcon",
    "ASSETCATALOG_COMPILER_GLOBAL_ACCENT_COLOR_NAME": "",
    "ENABLE_TESTABILITY": "YES",
    "SWIFT_DEFAULT_ACTOR_ISOLATION": "MainActor",
]

let appDependencies: [TargetDependency] = [
    .external(name: "WaypointCore"),
    .external(name: "Waypoint"),
    .external(name: "WaypointUIKit"),
]

// The UI tests compile the app's catalog and identifiers too, so a test names a screen with the
// same values the app uses.
let uiTestSources: SourceFilesList = [
    "WaypointExampleUITests/**",
    "WaypointExample/Catalog/**",
]

let uiTestDependencies: [TargetDependency] = [
    .target(name: "WaypointExample"),
]

// The unit tests run inside the app, so they reach its view models with `@testable import`. They
// are main actor by default, as the app is. The UI tests keep Swift's own default: XCUITest code
// isn't app code, and the catalog they share with the app is `nonisolated`.
let unitTestSettings: SettingsDictionary = [
    "SWIFT_DEFAULT_ACTOR_ISOLATION": "MainActor",
]

let unitTestSources: SourceFilesList = [
    "WaypointExampleTests/**",
]

let unitTestDependencies: [TargetDependency] = [
    .target(name: "WaypointExample"),
]

let app = Target.target(
    name: "WaypointExample",
    destinations: destinations,
    product: .app,
    bundleId: "dev.waypoint.example",
    deploymentTargets: deploymentTargets,
    infoPlist: .extendingDefault(with: infoPlistValues),
    sources: appSources,
    resources: appResources,
    dependencies: appDependencies,
    settings: .settings(base: appSettings)
)

let uiTests = Target.target(
    name: "WaypointExampleUITests",
    destinations: destinations,
    product: .uiTests,
    bundleId: "dev.waypoint.example.uitests",
    deploymentTargets: deploymentTargets,
    infoPlist: .default,
    sources: uiTestSources,
    dependencies: uiTestDependencies
)

let unitTests = Target.target(
    name: "WaypointExampleTests",
    destinations: destinations,
    product: .unitTests,
    bundleId: "dev.waypoint.example.tests",
    deploymentTargets: deploymentTargets,
    infoPlist: .default,
    sources: unitTestSources,
    dependencies: unitTestDependencies,
    settings: .settings(base: unitTestSettings)
)

let schemeBuildTargets: [TargetReference] = [
    "WaypointExample",
]

let schemeTestTargets: [TestableTarget] = [
    "WaypointExampleTests",
    "WaypointExampleUITests",
]

// After every build, in Xcode or a script, `tuist inspect build` sends the build's timings to the
// project's Tuist dashboard (Build Insights, #312). It runs Tuist through mise, which pins its
// version, and never fails a build: a Mac that isn't signed in to Tuist just sends nothing, and
// WAYPOINT_TUIST_OFFLINE=1 sends nothing. It takes the app's build settings, which it reads.
let buildInsightsScript = """
if [ "${WAYPOINT_TUIST_OFFLINE:-0}" = 1 ]; then
    exit 0
fi
MISE="$(command -v mise || echo "$HOME/.local/bin/mise")"
if [ -x "$MISE" ]; then
    eval "$("$MISE" activate -C "$SRCROOT" bash --shims)"
fi
if command -v tuist >/dev/null; then
    tuist inspect build || true
fi
"""

let buildInsights = ExecutionAction.executionAction(
    title: "Tuist build insights",
    scriptText: buildInsightsScript,
    target: "WaypointExample"
)

let scheme = Scheme.scheme(
    name: "WaypointExample",
    shared: true,
    buildAction: .buildAction(
        targets: schemeBuildTargets,
        postActions: [buildInsights],
        runPostActionsOnFailure: true
    ),
    testAction: .targets(schemeTestTargets),
    runAction: .runAction(executable: "WaypointExample")
)

let targets: [Target] = [
    app,
    unitTests,
    uiTests,
]

let schemes: [Scheme] = [
    scheme,
]

let project = Project(
    name: "WaypointExample",
    settings: .settings(base: baseSettings),
    targets: targets,
    schemes: schemes
)
